import { arduinoSketch, sampleBreadboard, setPreset } from "../src/lib/athena/circuit";
import { t } from "../src/lib/athena/i18n";
import { ARDUINO_LESSONS } from "../src/lib/athena/lessons";
import { runCheck } from "../src/lib/athena/sim/checks";

// Every Arduino lesson: the reference sketch generated by Athena IDE must pass the lesson's check, the starter must not.
// Run: npx tsx scripts/arduino-check.ts

let bad = 0;
for (const l of ARDUINO_LESSONS) {
  const g = setPreset(sampleBreadboard(), l.preset);
  const ref = l.id === "serial" ? `void setup() { Serial.begin(9600); Serial.println("Hello, BSTS!"); }\nvoid loop() {}\n` : arduinoSketch(g);
  const a = runCheck(g, ref, l.check);
  const b = runCheck(g, l.starter, l.check);
  const ok = a.pass && !b.pass;
  if (!ok) bad++;
  console.log(`${ok ? "OK  " : "FAIL"} ${l.id.padEnd(9)} reference: ${a.pass ? "pass" : `fail (${t(a.text, a.vars)})`} · starter: ${b.pass ? "PASSES (too easy)" : t(b.text, b.vars)}`);
}
process.exit(bad ? 1 : 0);
